description:
Copied from this post (by Ted Schwartz) in the forum:
http://www.jfree.org/phpBB2/viewtopic.php?t=24523
I've found a bug in jfreechart-1.0.9 code for org.jfree.data.xy.XYSeries. There was a change some time ago which introduced the notion of allowing duplicate X values in XYSeries data. The method addOrUpdate(Number x, Number y) was never modified to support this, and therefore duplicate data were overwriting existing data. This is the fix I've made, but I don't know how to submit a patch...
$ diff original/jfreechart-1.0.9/source/org/jfree/data/xy/XYSeries.java fixed/org/jfree/data/xy/XYSeries.java
537c537
< if (index >= 0) {
---
> if (index >= 0 && !allowDuplicateXValues) {
545a546,559
> } else if (index >= 0){
> XYDataItem item = new XYDataItem(x, y);
> // need to make sure we are adding *after* any duplicates
> int size = this.data.size();
> while (index < size
> && item.compareTo(this.data.get(index)) == 0) {
> index++;
> }
> if (index < this.data.size()) {
> this.data.add(index, item);
> }
> else {
> this.data.add(item);
> }
558,561d571
< // check if this addition will exceed the maximum item count...
< if (getItemCount() > this.maximumItemCount) {
< this.data.remove(0);
< }
562a573,576
> // check if this addition will exceed the maximum item count...
> if (getItemCount() > this.maximumItemCount) {
> this.data.remove(0);
> }

Issue Report
{"id":1053,"status":"Fixed","summary":"Overzealous optimization confuses variables","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":5,"comments":[{"id":0,"commenterId":-8406598521465938809,"content":"The following code:

	// ==ClosureCompiler==
	// @compilation_level ADVANCED_OPTIMIZATIONS
	// ==/ClosureCompiler==
	var uid;
	function reset() {
		uid = Math.random();
	}
	function doStuff() {
		reset();
		var _uid = uid;

		if (uid &lt; 0.5) {
			doStuff();
		}

		if (_uid !== uid) {
			throw 'reset() was called';
		}
	}
	doStuff();

...gets optimized to:

	var a;function b(){a=Math.random();0.5&gt;a&amp;&amp;b();if(a!==a)throw&quot;reset() was called&quot;;}b();

Notice how _uid gets optimized away and (uid!==_uid) becomes (a!==a) even though doStuff() might have been called and uid's value may have changed and become different from _uid.

As an aside, replacing the declaration with &quot;var _uid = +uid;&quot; fixes it, as does adding an extra &quot;uid = _uid&quot; after &quot;var _uid = uid&quot;.","timestamp":1375143403,"attachments":[]},{"id":1,"commenterId":-5060162230523776870,"content":"Thanks for the report!","timestamp":1375160481,"attachments":[]},{"id":2,"commenterId":-215138502632663007,"content":"Ya! Thanks for the nicely isolated bug report!

Looks like a (non flow sensitive) variable inlining bug.

After function inliner put down var _uid = uid = Math.random(), it might have gotten a bit too aggressive assuming _uid being replaceable by uid.

","timestamp":1375987953,"attachments":[]},{"id":3,"commenterId":-215138502632663007,"content":"I have a patch that is currently in review. It should be fixed in the next release.","timestamp":1375991834,"attachments":[]},{"id":4,"commenterId":-8769171937076622550,"content":"This issue was closed by revision 0123fd5303c8.","timestamp":1376443730,"attachments":[]}]}

Issue Report
{"id":937,"status":"Fixed","summary":"Casting a function before calling it produces bad code and breaks plugin code","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":3,"comments":[{"id":0,"commenterId":177012085138132463,"content":"1. Compile this code with ADVANCED_OPTIMIZATIONS:
console.log( /** @type {function(!string):!string} */ ((new window.ActiveXObject( 'ShockwaveFlash.ShockwaveFlash' ))['GetVariable'])( '$version' ) );

produces:

'use strict';console.log((0,(new window.ActiveXObject(&quot;ShockwaveFlash.ShockwaveFlash&quot;)).GetVariable)(&quot;$version&quot;));

2. Compare with this code:
console.log( /** @type {!string} */ ((new window.ActiveXObject( 'ShockwaveFlash.ShockwaveFlash' ))['GetVariable']( '$version' )) )

produces:

'use strict';console.log((new window.ActiveXObject(&quot;ShockwaveFlash.ShockwaveFlash&quot;)).GetVariable(&quot;$version&quot;));


Notice the (0,...) wrapping around the GetVariable function in the first example. This causes the call to fail in every browser (this code is IE-only but it's just for a minimal example). The second version produces a warning that the type of GetVariable could not be determined (I enabled type warnings), and it wouldn't be possible to define these in an externs file without making a horrible mess.

This applies to all cases where functions are cast, but only causes problems (other than bloat) with plugins like this. It seems to serve no purpose whatsoever, so I assume it is a bug.

Running on a mac, not sure what version but it reports Built on: 2013/02/12 17:00, so will have been downloaded about that time.","timestamp":1362505862,"attachments":[]},{"id":1,"commenterId":-5060162230523776870,"content":"Well drat. This seems likely that this is a side effect of the introduction of the CAST node to the AST.  I'll take a look.","timestamp":1362585536,"attachments":[]},{"id":2,"commenterId":-8769171937076622550,"content":"This issue was closed by revision 79a8906570f4.","timestamp":1363798292,"attachments":[]}]}

Issue Report
{"id":787,"status":"Fixed","summary":"true/false are not always replaced for !0/!1","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":3,"comments":[{"id":0,"commenterId":-2177134355389785939,"content":"<b>What steps will reproduce the problem?</b>

function some_function() {
  var fn1;
  var fn2;

  if (any_expression) {
    fn2 = external_ref;
    fn1 = function (content) {
      return fn2();
    }
  }

  return {
    method1: function () {
      if (fn1) fn1();
      return true;
    },
    method2: function () {
      return false;
    }
  }
}

<b>What is the expected output? What do you see instead?</b>

We expect that true/false will be replaced for !0/!1, but it doesn't happend.

function some_function() {
  var a, b;
  any_expression &amp;&amp; (b = external_ref, a = function () {
    return b()
  });
  return {
    method1: function () {
      a &amp;&amp; a();
      return true
    },
    method2: function () {
      return false
    }
  }
};

<b>What version of the product are you using? On what operating system?</b>

This is output for latest official build.
I also got the same output for 20120430, 20120305. But 20111117 is OK.

<b>Please provide any additional information below.</b>

Here is just one of example. I found too many non-replaced true/false in compiler output. Replacement non-replaced true/false to !1/!0 in conpiler output saves 1-2 kb for 850 kb js file.","timestamp":1343813264,"attachments":[]},{"id":1,"commenterId":-5060162230523776870,"content":"The peephole optimizations are being short circuited, I'm pretty sure I caused this problem so I'll look into it.","timestamp":1343847526,"attachments":[]},{"id":2,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r2119.","timestamp":1344005344,"attachments":[]}]}

Issue Report
{"id":124,"status":"Fixed","summary":"Invalid JSC_DETERMINISTIC_TEST","labels":["Type-Defect","Priority-Medium"],"stars":1,"commentCount":3,"comments":[{"id":0,"commenterId":4411030986668650696,"content":"<b>What steps will reproduce the problem?</b>

1. Compile following code:

// ==ClosureCompiler==
// @output_file_name default.js
// @compilation_level ADVANCED_OPTIMIZATIONS
// ==/ClosureCompiler==

var t = null;

window.test = function()
{
    if (t != null)
    {
       t = null;
    }

    t = 1;
};

<b>What is the expected output? What do you see instead?</b>

Code should be compiled without warnings, but I see 
&quot;JSC_DETERMINISTIC_TEST: condition always evaluates to false&quot;.","timestamp":1268714411,"attachments":[]},{"id":1,"commenterId":-7699928860083865744,"content":"thanks for the report.

the immediate work around is to have a @type {?number} annotation on the global 
variable.","timestamp":1268758994,"attachments":[]},{"id":2,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r142.","timestamp":1268952668,"attachments":[]}]}

Issue Report
{"id":58,"status":"Fixed","summary":"Internet Explorer runtime error after compilation.","labels":["Type-Defect","Priority-Medium"],"stars":4,"commentCount":10,"comments":[{"id":0,"commenterId":7777975795178686730,"content":"<b>What steps will reproduce the problem?</b>
See attached HTML file in IE6+ (does not work in IE8 unless Compatibility View is turned *on* for 
some reason).

<b>What is the expected output? What do you see instead?</b>
Expected output is on the left-hand side of the page (it is generated by the raw source). Google 
Closure's output is on the right-hand side of the page.

<b>What version of the product are you using? On what operating system?</b>
I downloaded compiler-latest.zip today (Nov. 24, 2009, ~ 12:00 PM EST)

<b>Please provide any additional information below.</b>
There is a variable called &quot;threshold&quot; which is used to generate an array of arrays in the attached 
HTML file. If it is a small number, IE seems to pass arrays into the sort method (sorting an array 
of arrays) by value like all other browsers do. But when threshold is large enough (on my 
machine that happens around 250) IE starts passing the arrays in by value. Google Closure 
compiler has changed my original source from making local copies to modifying the arguments 
being passed into the sort comparator ... but as a result of this IE behavior the Closure compiled 
code breaks.","timestamp":1259084060,"attachments":[{"id":2881320297632167502,"fileName":"googleclosuretest.html","fileSize":1695}]},{"id":1,"commenterId":7777975795178686730,"content":"So after looking into this some more, I've learned that arrays are always passed by reference, but that only 
means you can change attributes and individual items in an array. So for example:

var a = [1, 2, 3, 4];
var f = function(x){x = null;};
f(a);
// the value of a will remain [1, 2, 3, 4]
// but if instead:
var g = function(x){x[0] = null;};
g(a);
// the value of a is now [null, 2, 3, 4]

In the attached example, the Google Closure compiled version is akin to the function f above, which means 
that the value of the arrays should *not* be changing. In IE, if the threshold is set high enough, however, they 
do indeed change. So the original report may not be accurate, but this is a real issue.","timestamp":1259105000,"attachments":[]},{"id":2,"commenterId":-5060162230523776870,"content":"There is definitely something odd occurring here, running it under the debugger with 
IE7, it reports "Number expected".

Adding a "Debug.writeln("blah")" in the "right" spot and the problem goes away:
    var g_test=function(f,c){
        var g=["aaaaaa","bbbbbb"];
        c=(function(a,b){
          for(var d=[],e=0;e<a;e+=1)
            d.push(b);
          return d})(c,g);
        c.sort(function(a,b){
          a=(a[1].toUpperCase());
          Debug.writeln("Blah");
          b=(b[1].toUpperCase());
          return a<b?-1:Number(a>b)});
        f.innerHTML=typeof c[0]+"<br>"+c.join(" --- ")
     };","timestamp":1259115134,"attachments":[]},{"id":3,"commenterId":-5060162230523776870,"content":"Update summary to something more directly related.","timestamp":1259201167,"attachments":[]},{"id":4,"commenterId":-5917403417089514098,"content":"","timestamp":1259707252,"attachments":[]},{"id":5,"commenterId":4690000788079557483,"content":"I did some research on this issue, documented here:
http://www.zachleat.com/web/2010/02/24/array-sort/","timestamp":1267068145,"attachments":[]},{"id":6,"commenterId":4690000788079557483,"content":"If you don't want to wait for the compiler fix, just declare the variables outside of 
the sort, and the compiler won't optimize and reuse them:

var a, b;
c.sort(function(a1,b1){
          a=(a1[1].toUpperCase());
          Debug.writeln("Blah");
          b=(b1[1].toUpperCase());
          return a<b?-1:Number(a>b)});","timestamp":1267106534,"attachments":[]},{"id":7,"commenterId":-7699928860083865744,"content":"wow. that's a nice find. i can't imagine what IE could possibly be doing under the 
covers that would lead to this problem.

One possible fix would be to never coalesce the arguments of a function. 

Another possible fix would be to "fix" Array.prototype.sort:

var oldArraySort = Array.prototype.sort;
Array.prototype.sort = function(f) {
  return oldArraySort.call(this, function(x, y) {
    return f.call(this, x, y);
  });
};

Neither is really satisfying.

Alan, what do you think?","timestamp":1267151828,"attachments":[]},{"id":8,"commenterId":5241484814466034803,"content":"Perhaps a @nocoalesce JSDoc tag?","timestamp":1267920870,"attachments":[]},{"id":9,"commenterId":-7699928860083865744,"content":"fixed by r171","timestamp":1270537715,"attachments":[]}]}

Issue Report
{"id":172,"status":"Fixed","summary":"bad type inference for != undefined","labels":["Type-Defect","Priority-Medium"],"stars":1,"commentCount":2,"comments":[{"id":0,"commenterId":-7699928860083865744,"content":"<b>What steps will reproduce the problem?</b>

// ==ClosureCompiler==
// @compilation_level ADVANCED_OPTIMIZATIONS
// @output_file_name default.js
// ==/ClosureCompiler==

/** @param {string} x */
function g(x) {}

/** @param {undefined} x */
function f(x) {
  if (x != undefined) { g(x); }
}

<b>What is the expected output? What do you see instead?</b>

JSC_DETERMINISTIC_TEST: condition always evaluates to false
left : undefined
right: undefined at line 6 character 6
if (x != undefined) { g(x); }
      ^
JSC_TYPE_MISMATCH: actual parameter 1 of g does not match formal parameter
found   : undefined
required: string at line 6 character 24
if (x != undefined) { g(x); }
                        ^

the second warning is bogus.

","timestamp":1275609991,"attachments":[]},{"id":1,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r265.","timestamp":1278540868,"attachments":[]}]}

Issue Report
{"id":773,"status":"Fixed","summary":"Switched order of "delete key" and "key in" statements changes semantic","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":5,"comments":[{"id":0,"commenterId":-6885360950181397962,"content":"// Input:

var customData = { key: 'value' };

function testRemoveKey( key ) {
	var dataSlot = customData,
		retval = dataSlot &amp;&amp; dataSlot[ key ],
		hadKey = dataSlot &amp;&amp; ( key in dataSlot );

	if ( dataSlot )
		delete dataSlot[ key ];

	return hadKey ? retval : null;
};

console.log( testRemoveKey( 'key' ) ); // 'value'
console.log( 'key' in customData ); // false


// Compiled version:

var customData={key:&quot;value&quot;};function testRemoveKey(b){var a=customData,c=a&amp;&amp;a[b];a&amp;&amp;delete a[b];return a&amp;&amp;b in a?c:null}console.log(testRemoveKey(&quot;key&quot;));console.log(&quot;key&quot;in customData);

// null
// false


&quot;b in a&quot; is executed after &quot;delete a[b]&quot; what obviously doesn't make sense in this case.


Reproducible on: http://closure-compiler.appspot.com/home and in &quot;Version: 20120430 (revision 1918) Built on: 2012/04/30 18:02&quot;","timestamp":1341844793,"attachments":[]},{"id":1,"commenterId":-7699928860083865744,"content":"ack. thanks for the report","timestamp":1341848778,"attachments":[]},{"id":2,"commenterId":-7699928860083865744,"content":"john figured this out first.","timestamp":1341866393,"attachments":[]},{"id":3,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r2079.","timestamp":1341936108,"attachments":[]},{"id":4,"commenterId":-6885360950181397962,"content":"Thanks for quick patch :).","timestamp":1342427449,"attachments":[]}]}

Issue Report
{"id":61,"status":"Fixed","summary":"Type checker misses annotations on functions defined within functions","labels":["Type-Defect","Priority-Medium"],"stars":7,"commentCount":7,"comments":[{"id":0,"commenterId":-2383702226191207389,"content":"<b>What steps will reproduce the problem?</b>
1. Compile the following code under --warning_level VERBOSE

var ns = {};

/** @param {string=} b */
ns.a = function(b) {}

function d() {
    ns.a();
    ns.a(123);
}

2. Observe that the type checker correctly emits one warning, as 123 
doesn't match the type {string}

3. Now compile the code with ns.a defined within an anonymous function, 
like so:

var ns = {};

(function() {
    /** @param {string=} b */
    ns.a = function(b) {}
})();

function d() {
    ns.a();
    ns.a(123);
}

4. Observe that a warning is emitted for calling ns.a with 0 parameters, and 
not for the type error, as though the @param declaration were ignored. 

<b>What version of the product are you using? On what operating system?</b>
r15

<b>Please provide any additional information below.</b>

This sort of module pattern is common enough that it strikes me as worth 
supporting.

One last note to make matters stranger: if the calling code isn't itself within 
a function, no warnings are emitted at all:

var ns = {};

(function() {
    /** @param {string=} b */
    ns.a = function(b) {}
})();

ns.a();
ns.a(123);
","timestamp":1259166883,"attachments":[]},{"id":1,"commenterId":-7699928860083865744,"content":"thanks for the report. I vaguely recall there was a very specific reason why this
case wasn't handled, but I think that reason might have gone away. I'll play with it
again and report back.","timestamp":1259811145,"attachments":[]},{"id":2,"commenterId":-7699928860083865744,"content":"notice that if you define ns.a in a local scope, and use it in a later scope, this will now work.

i'm still working on the case where you define ns.a in a local scope and call it from a global scope.","timestamp":1284825419,"attachments":[]},{"id":3,"commenterId":-5060162230523776870,"content":"Nick, this specific issue is fixed any reason not to close this?","timestamp":1285950211,"attachments":[]},{"id":4,"commenterId":-7699928860083865744,"content":"nope, the specific issue is not fixed. did you read my last comment?","timestamp":1285956282,"attachments":[]},{"id":5,"commenterId":-5060162230523776870,"content":"I understand now.  #3 is fixed now but not the call from global scope.","timestamp":1285962471,"attachments":[]},{"id":6,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r2240.","timestamp":1349452255,"attachments":[]}]}

Issue Report
{"id":772,"status":"Fixed","summary":"JSCompiler does not recursively resolve typedefs","labels":["Type-Defect","Priority-Medium"],"stars":0,"commentCount":6,"comments":[{"id":0,"commenterId":1197285801394374144,"content":"goog.provide('a.b.c');

goog.scope(function() {
var b = a.b;
var c = b.c;

/** @typedef {string} */
c.MyType;

/** @param {c.MyType} x The variable. */
c.myFunc = function(x) {};

});

results in a compiler error.

given that JSCompiler *does* recursively resolve other names, this appears to be a bug rather than an intended limitation.
","timestamp":1341588386,"attachments":[]},{"id":1,"commenterId":8173196008570380122,"content":"I'm fairly certain that typedefs have to be in the global scope. Although I'm not sure that has been documented anywhere or is the intent.

If you remove the goog.scope wrapper, your code compiles correctly.","timestamp":1341590139,"attachments":[]},{"id":2,"commenterId":1197285801394374144,"content":"no, typedefs don't have to be in the global scope. goog.scope must enclose everything in the file except goog.provide/goog.require","timestamp":1341590346,"attachments":[]},{"id":3,"commenterId":8173196008570380122,"content":"Scope affects it in some way. Here's test code:

var foo = {};
/** @typedef {string} */
foo.bar;

/** @typedef {string} */
var foo2;

var foo3 = {};

(function() {

/** @typedef {string} */
foo3.bar;
/** @typedef {string} */
var foo4;

var foo5 = {};
/** @typedef {string} */
foo5.bar;

/** @param {foo.bar} x The variable. */
var myFunc = function(x) {}; // No errors

/** @param {foo2} x The variable. */
var myFunc2 = function(x) {}; // No errors

/** @param {foo3.bar} x The variable. */
var myFunc3 = function(x) {}; // Unknown type error

/** @param {foo4} x The variable. */
var myFunc4 = function(x) {}; // Unknown type error

/** @param {foo5.bar} x The variable. */
var myFunc5 = function(x) {}; // Unknown type error
})();","timestamp":1341592248,"attachments":[]},{"id":4,"commenterId":-7699928860083865744,"content":"for the record, the error message is:
JSC_TYPE_PARSE_ERROR: Bad type annotation. Unknown type c.MyType at line 10 character 12
/** @param {c.MyType} x The variable. */
","timestamp":1341702258,"attachments":[]},{"id":5,"commenterId":-7699928860083865744,"content":"This issue was closed by revision r2077.","timestamp":1341869432,"attachments":[]}]}

